"""Offline grid contracts for the sweep-to-atlas bridge (#2118)."""

from types import SimpleNamespace

import numpy as np
import pandas as pd
import pytest

from digitalmodel.parametrics import ParameterSweep, ParametricStudy
from digitalmodel.parametrics import atlas_bridge


# Independently enumerated, rather than generated by the study under test.
POINTS = [(0, 0), (0, 1), (0, 2), (1, 0), (1, 1), (1, 2), (2, 0), (2, 1), (2, 2)]


@pytest.fixture
def study():
    return ParametricStudy(
        name="synthetic",
        parameters=[
            ParameterSweep(name="x", values=[0, 1, 2]),
            ParameterSweep(name="y", values=[0, 1, 2]),
        ],
    )


@pytest.fixture
def frame():
    return pd.DataFrame(
        [
            {"x": x, "y": y, "metric": x + 10 * y, "status": "completed"}
            for x, y in POINTS
        ]
    )


@pytest.fixture
def no_atlas(monkeypatch):
    def forbidden(**kwargs):
        pytest.fail("invalid grid reached Atlas construction")

    monkeypatch.setattr(atlas_bridge, "Atlas", forbidden)


def build(study, frame, response="metric"):
    summary = SimpleNamespace(to_dataframe=lambda: frame)
    return atlas_bridge.atlas_from_summary(
        study, summary, response, basename="synthetic", atlas_id="grid-test"
    )


@pytest.mark.parametrize("fault", ["duplicate", "outside", "missing", "extra"])
def test_requires_exact_unique_cartesian_membership(study, frame, no_atlas, fault):
    if fault == "duplicate":
        frame.loc[8, ["x", "y"]] = [0, 0]  # nine rows, missing (2, 2)
    elif fault == "outside":
        frame.loc[8, ["x", "y"]] = [3, 2]  # nine unique rows, wrong node
    elif fault == "missing":
        frame = frame.iloc[:-1]
    else:
        frame = pd.concat([frame, frame.iloc[:1]], ignore_index=True)
    with pytest.raises(ValueError, match="full-factorial"):
        build(study, frame)


@pytest.mark.parametrize("column", ["x", "y", "metric"])
@pytest.mark.parametrize("value", [np.nan, np.inf, -np.inf])
def test_rejects_nonfinite_rows(study, frame, no_atlas, column, value):
    frame[column] = frame[column].astype(float)
    frame.loc[0, column] = value
    with pytest.raises(ValueError, match="finite"):
        build(study, frame)


@pytest.mark.parametrize("column", ["x", "y", "metric"])
@pytest.mark.parametrize("value", ["0", True, np.bool_(False), None, 1 + 0j])
def test_rejects_coercible_or_nonnumeric_rows(study, frame, no_atlas, column, value):
    frame[column] = frame[column].astype(object)
    frame.loc[0, column] = value
    with pytest.raises(ValueError, match="numeric"):
        build(study, frame)


@pytest.mark.parametrize(
    "values",
    [
        [],
        [0, 0, 2],
        [0, np.nan, 2],
        [0, np.inf, 2],
        [0, -np.inf, 2],
        [0, "1", 2],
        [0, True, 2],
        [0, np.bool_(True), 2],
        [0, None, 2],
        [0, 1 + 0j, 2],
    ],
)
def test_rejects_invalid_declared_knots(study, frame, no_atlas, values):
    # Preserve get_values() inputs without Pydantic first coercing strings/bools.
    study.parameters[0] = study.parameters[0].model_copy(update={"values": values})
    with pytest.raises(ValueError, match="axis.*(empty|unique|numeric|finite)"):
        build(study, frame)


@pytest.mark.parametrize("names", [[], ["x", "x"]])
def test_rejects_empty_or_duplicate_parameter_names(study, frame, no_atlas, names):
    study.parameters = [ParameterSweep(name=name, values=[0, 1, 2]) for name in names]
    with pytest.raises(ValueError, match="parameters.*(no|unique)|no parameters"):
        build(study, frame)


@pytest.mark.parametrize("column", ["status", "x", "y", "metric"])
def test_rejects_missing_selected_columns(study, frame, no_atlas, column):
    with pytest.raises(ValueError, match="column"):
        build(study, frame.drop(columns=column))


def test_preserves_unknown_response_error(study, frame, no_atlas):
    with pytest.raises(ValueError, match="response 'unknown' not in result columns"):
        build(study, frame, response="unknown")


def test_failed_node_does_not_complete_grid(study, frame, no_atlas):
    frame.loc[8, "status"] = "failed"
    with pytest.raises(ValueError, match="full-factorial"):
        build(study, frame)


def test_clean_shuffled_rows_preserve_values_and_input(study, frame):
    original = frame.copy(deep=True)
    shuffled = frame.sample(frac=1, random_state=2118)
    shuffled_original = shuffled.copy(deep=True)
    clean = build(study, frame)
    reordered = build(study, shuffled)
    expected = original[["x", "y", "metric"]]
    pd.testing.assert_frame_equal(clean.grid, expected)
    pd.testing.assert_frame_equal(reordered.grid, expected)
    pd.testing.assert_frame_equal(frame, original)
    pd.testing.assert_frame_equal(shuffled, shuffled_original)
    assert [axis.grid for axis in clean.axes] == [[0, 1, 2], [0, 1, 2]]
    assert clean.grid.loc[0, "metric"] == 0  # numerical zero remains valid


def test_ignores_uncompleted_rows(study, frame):
    ignored = pd.DataFrame(
        [
            {"x": np.inf, "y": np.nan, "metric": True, "status": status}
            for status in ["failed", "pending", "prepared"]
        ]
    )
    combined = pd.concat([frame, ignored], ignore_index=True)
    original = combined.copy(deep=True)
    atlas = build(study, combined)
    assert list(atlas.grid.itertuples(index=False, name=None)) == [
        (x, y, x + 10 * y) for x, y in POINTS
    ]
    pd.testing.assert_frame_equal(combined, original)
